def seed_permissions(apps: "Apps", schema_editor: "BaseDatabaseSchemaEditor") -> None:
    """Insert the permission catalog (DB mirror of core/permissions/catalog.py)."""
    permission_model = apps.get_model("accounts", "Permission")
    for perm in PERMISSIONS:
        permission_model.objects.update_or_create(
            code=perm.code,
            defaults={
                "module": perm.module,
                "name": perm.name,
                "is_sensitive": perm.sensitive,
            },
        )


def unseed_permissions(apps: "Apps", schema_editor: "BaseDatabaseSchemaEditor") -> None:
    """Reverse of seed_permissions: remove exactly the seeded codes."""
    permission_model = apps.get_model("accounts", "Permission")
    permission_model.objects.filter(code__in=[p.code for p in PERMISSIONS]).delete()


